package com.c203.limit.domain.withdrawal.entity;
import java.time.OffsetDateTime; import com.c203.limit.domain.member.entity.Member; import com.c203.limit.global.exception.*; import jakarta.persistence.*;
@Entity @Table(name="withdrawal_request") public class WithdrawalRequest{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="withdrawal_request_id") private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private Member member;@Column(name="withdrawal_reason",nullable=false,length=500)private String reason;@Column(nullable=false)private String status;@Column(name="blocked_reason",length=500)private String blockedReason;@Column(name="requested_at",nullable=false)private OffsetDateTime requestedAt;@Column(name="processed_at")private OffsetDateTime processedAt;@Column(name="processed_admin_id")private Long processedAdminId;
 protected WithdrawalRequest(){} public void process(Long admin,String decision,String blocked){if(!java.util.Set.of("REQUESTED","BLOCKED").contains(status))throw new BusinessException(ErrorCode.INVALID_INPUT_VALUE);if("BLOCK".equals(decision)){if(blocked==null||blocked.isBlank())throw new BusinessException(ErrorCode.INVALID_INPUT_VALUE);status="BLOCKED";blockedReason=blocked;}else if("COMPLETE".equals(decision)){status="COMPLETED";blockedReason=null;member.completeWithdrawal();}else throw new BusinessException(ErrorCode.INVALID_INPUT_VALUE);processedAdminId=admin;processedAt=OffsetDateTime.now();}
 public Long getId(){return id;}public Member getMember(){return member;}public String getReason(){return reason;}public String getStatus(){return status;}public String getBlockedReason(){return blockedReason;}public OffsetDateTime getRequestedAt(){return requestedAt;}public OffsetDateTime getProcessedAt(){return processedAt;}public Long getProcessedAdminId(){return processedAdminId;}
}
